   254→// Pause pauses the component and its underlying process.
   255→func (m *Miner) Pause() error {
   256→	return m.cmd.Process.Signal(syscall.SIGSTOP)
   257→}
   258→
   259→// Resume resumes the component and its underlying process.
   260→func (m *Miner) Resume() error {
   261→	return m.cmd.Process.Signal(syscall.SIGCONT)
   262→}
   263→
   264→// Stop kills the component and its underlying process.
   265→func (m *Miner) Stop() error {
   266→	return m.cmd.Process.Kill()
   267→}
