   269→func enodeFromLogFile(name string) (string, error) {
   270→	byteContent, err := os.ReadFile(name) // #nosec G304
   271→	if err != nil {
   272→		return "", err
   273→	}
   274→	contents := string(byteContent)
   275→
   276→	searchText := "self=enode://"
   277→	startIdx := strings.Index(contents, searchText)
   278→	if startIdx == -1 {
   279→		return "", fmt.Errorf("did not find ENR text in %s", contents)
   280→	}
   281→	startIdx += len(searchText)
   282→	endIdx := strings.Index(contents[startIdx:], "@")
   283→	if endIdx == -1 {
   284→		return "", fmt.Errorf("did not find ENR text in %s", contents)
   285→	}
   286→	enode := contents[startIdx : startIdx+endIdx]
   287→	return strings.TrimPrefix(enode, "-"), nil
   288→}
