    37→type TransactionGenerator struct {
    38→	keystore string
    39→	seed     int64
    40→	started  chan struct{}
    41→	cancel   context.CancelFunc
    42→	paused   bool
    43→}
    44→
    45→func (t *TransactionGenerator) UnderlyingProcess() *os.Process {
    46→	// Transaction Generator runs under the same underlying process so
    47→	// we return an empty process object.
    48→	return &os.Process{}
    49→}
    50→
    51→func NewTransactionGenerator(keystore string, seed int64) *TransactionGenerator {
    52→	return &TransactionGenerator{keystore: keystore, seed: seed}
    53→}
    54→
    55→func (t *TransactionGenerator) Start(ctx context.Context) error {
    56→	// Wrap context with a cancel func
    57→	ctx, ccl := context.WithCancel(ctx)
    58→	t.cancel = ccl
    59→
    60→	client, err := rpc.DialHTTP(fmt.Sprintf("http://127.0.0.1:%d", e2e.TestParams.Ports.Eth1RPCPort))
    61→	if err != nil {
    62→		return err
    63→	}
    64→	defer client.Close()
    65→
    66→	seed := t.seed
    67→	newGen := rand.NewDeterministicGenerator()
    68→	if seed == 0 {
    69→		seed = newGen.Int63()
    70→		logrus.Infof("Seed for transaction generator is: %d", seed)
    71→	}
    72→	// Set seed so that all transactions can be
    73→	// deterministically generated.
    74→	mathRand.Seed(seed)
    75→
    76→	keystoreBytes, err := os.ReadFile(t.keystore) // #nosec G304
    77→	if err != nil {
    78→		return err
    79→	}
    80→	mineKey, err := keystore.DecryptKey(keystoreBytes, KeystorePassword)
    81→	if err != nil {
    82→		return err
    83→	}
    84→	newKey := keystore.NewKeyForDirectICAP(newGen)
    85→	if err := fundAccount(client, mineKey, newKey); err != nil {
    86→		return err
    87→	}
    88→	fundedAccount = newKey
    89→	rnd := make([]byte, 10000)
    90→	_, err = mathRand.Read(rnd) // #nosec G404
    91→	if err != nil {
    92→		return err
    93→	}
    94→	f := filler.NewFiller(rnd)
    95→	// Broadcast Transactions every slot
    96→	txPeriod := time.Duration(params.BeaconConfig().SecondsPerSlot) * time.Second
    97→	ticker := time.NewTicker(txPeriod)
    98→	gasPrice := big.NewInt(1e11)
    99→	for {
   100→		select {
   101→		case <-ctx.Done():
   102→			return nil
   103→		case <-ticker.C:
   104→			if t.paused {
   105→				continue
   106→			}
   107→			backend := ethclient.NewClient(client)
   108→			err = SendTransaction(client, mineKey.PrivateKey, f, gasPrice, mineKey.Address.String(), txCount, backend, false)
   109→			if err != nil {
   110→				return err
   111→			}
   112→			backend.Close()
   113→		}
   114→	}
   115→}
