   122→func SendTransaction(client *rpc.Client, key *ecdsa.PrivateKey, f *filler.Filler, gasPrice *big.Int, addr string, N uint64, backend *ethclient.Client, al bool) error {
   123→	sender := common.HexToAddress(addr)
   124→	nonce, err := backend.PendingNonceAt(context.Background(), fundedAccount.Address)
   125→	if err != nil {
   126→		return err
   127→	}
   128→	chainid, err := backend.ChainID(context.Background())
   129→	if err != nil {
   130→		return err
   131→	}
   132→	expectedPrice, err := backend.SuggestGasPrice(context.Background())
   133→	if err != nil {
   134→		return err
   135→	}
   136→	if expectedPrice.Cmp(gasPrice) > 0 {
   137→		gasPrice = expectedPrice
   138→	}
   139→	g, _ := errgroup.WithContext(context.Background())
   140→	txs := make([]*types.Transaction, 10)
   141→	for i := uint64(0); i < 10; i++ {
   142→		index := i
   143→		g.Go(func() error {
   144→			tx, err := RandomBlobTx(client, f, fundedAccount.Address, nonce+index, gasPrice, chainid, al)
   145→			if err != nil {
   146→				logrus.WithError(err).Error("Could not create blob tx")
   147→				// In the event the transaction constructed is not valid, we continue with the routine
   148→				// rather than complete stop it.
   149→				//nolint:nilerr
   150→				return nil
   151→			}
   152→			signedTx, err := types.SignTx(tx, types.NewCancunSigner(chainid), fundedAccount.PrivateKey)
   153→			if err != nil {
   154→				logrus.WithError(err).Error("Could not sign blob tx")
   155→				// We continue on in the event there is a reason we can't sign this
   156→				// transaction(unlikely).
   157→				//nolint:nilerr
   158→				return nil
   159→			}
   160→			txs[index] = signedTx
   161→			return nil
   162→		})
   163→	}
   164→
   165→	if err := g.Wait(); err != nil {
   166→		return err
   167→	}
   168→	for _, tx := range txs {
   169→		if tx == nil {
   170→			continue
   171→		}
   172→		err = backend.SendTransaction(context.Background(), tx)
   173→		if err != nil {
   174→			// Do nothing
   175→			continue
   176→		}
   177→	}
   178→
   179→	nonce, err = backend.PendingNonceAt(context.Background(), sender)
   180→	if err != nil {
   181→		return err
   182→	}
   183→
   184→	txs = make([]*types.Transaction, N)
   185→	for i := uint64(0); i < N; i++ {
   186→		index := i
   187→		g.Go(func() error {
   188→			tx, err := txfuzz.RandomValidTx(client, f, sender, nonce+index, gasPrice, chainid, al)
   189→			if err != nil {
   190→				// In the event the transaction constructed is not valid, we continue with the routine
   191→				// rather than complete stop it.
   192→				//nolint:nilerr
   193→				return nil
   194→			}
   195→			signedTx, err := types.SignTx(tx, types.NewLondonSigner(chainid), key)
   196→			if err != nil {
   197→				// We continue on in the event there is a reason we can't sign this
   198→				// transaction(unlikely).
   199→				//nolint:nilerr
   200→				return nil
   201→			}
   202→			txs[index] = signedTx
   203→			return nil
   204→		})
   205→	}
   206→	if err := g.Wait(); err != nil {
   207→		return err
   208→	}
   209→	for _, tx := range txs {
   210→		if tx == nil {
   211→			continue
   212→		}
   213→		err = backend.SendTransaction(context.Background(), tx)
   214→		if err != nil {
   215→			// Do nothing
   216→			continue
   217→		}
   218→	}
   219→	return nil
   220→}
