   240→func RandomBlobTx(rpc *rpc.Client, f *filler.Filler, sender common.Address, nonce uint64, gasPrice, chainID *big.Int, al bool) (*types.Transaction, error) {
   241→	// Set fields if non-nil
   242→	if rpc != nil {
   243→		client := ethclient.NewClient(rpc)
   244→		var err error
   245→		if gasPrice == nil {
   246→			gasPrice, err = client.SuggestGasPrice(context.Background())
   247→			if err != nil {
   248→				gasPrice = big.NewInt(1)
   249→			}
   250→		}
   251→		if chainID == nil {
   252→			chainID, err = client.ChainID(context.Background())
   253→			if err != nil {
   254→				chainID = big.NewInt(1)
   255→			}
   256→		}
   257→	}
   258→	gas := uint64(100000)
   259→	to := randomAddress()
   260→	code := txfuzz.RandomCode(f)
   261→	value := big.NewInt(0)
   262→	if len(code) > 128 {
   263→		code = code[:128]
   264→	}
   265→	mod := 2
   266→	if al {
   267→		mod = 1
   268→	}
   269→	switch f.Byte() % byte(mod) {
   270→	case 0:
   271→		// 4844 transaction without AL
   272→		tip, feecap, err := getCaps(rpc, gasPrice)
   273→		if err != nil {
   274→			return nil, errors.Wrap(err, "getCaps")
   275→		}
   276→		data, err := randomBlobData()
   277→		if err != nil {
   278→			return nil, errors.Wrap(err, "randomBlobData")
   279→		}
   280→		return New4844Tx(nonce, &to, gas, chainID, tip, feecap, value, code, big.NewInt(1000000), data, make(types.AccessList, 0)), nil
   281→	case 1:
   282→		// 4844 transaction with AL nonce, to, value, gas, gasPrice, code
   283→		tx := types.NewTx(&types.LegacyTx{
