   285→			To:       &to,
   286→			Value:    value,
   287→			Gas:      gas,
   288→			GasPrice: gasPrice,
   289→			Data:     code,
   290→		})
   291→
   292→		// TODO: replace call with al, err := txfuzz.CreateAccessList(rpc, tx, sender) when txfuzz is fixed in new release
   293→		// an error occurs mentioning error="CreateAccessList: both gasPrice and (maxFeePerGas or maxPriorityFeePerGas) specified"
   294→		msg := ethereum.CallMsg{
   295→			From:       sender,
   296→			To:         tx.To(),
   297→			Gas:        tx.Gas(),
   298→			GasPrice:   tx.GasPrice(),
   299→			Value:      tx.Value(),
   300→			Data:       tx.Data(),
   301→			AccessList: nil,
   302→		}
   303→		geth := gethclient.New(rpc)
   304→		al, _, _, err := geth.CreateAccessList(context.Background(), msg)
   305→		if err != nil {
   306→			return nil, errors.Wrap(err, "CreateAccessList")
   307→		}
   308→		tip, feecap, err := getCaps(rpc, gasPrice)
   309→		if err != nil {
   310→			return nil, errors.Wrap(err, "getCaps")
   311→		}
   312→		data, err := randomBlobData()
   313→		if err != nil {
   314→			return nil, errors.Wrap(err, "randomBlobData")
   315→		}
   316→		return New4844Tx(nonce, &to, gas, chainID, tip, feecap, value, code, big.NewInt(1000000), data, *al), nil
   317→	}
   318→	return nil, errors.New("asdf")
