   321→func New4844Tx(nonce uint64, to *common.Address, gasLimit uint64, chainID, tip, feeCap, value *big.Int, code []byte, blobFeeCap *big.Int, blobData []byte, al types.AccessList) *types.Transaction {
   322→	blobs, comms, proofs, versionedHashes, err := EncodeBlobs(blobData)
   323→	if err != nil {
   324→		panic(err) // lint:nopanic -- Test code.
   325→	}
   326→	tx := types.NewTx(&types.BlobTx{
   327→		ChainID:    uint256.MustFromBig(chainID),
   328→		Nonce:      nonce,
   329→		GasTipCap:  uint256.MustFromBig(tip),
   330→		GasFeeCap:  uint256.MustFromBig(feeCap),
   331→		Gas:        gasLimit,
   332→		To:         *to,
   333→		Value:      uint256.MustFromBig(value),
   334→		Data:       code,
   335→		AccessList: al,
   336→		BlobFeeCap: uint256.MustFromBig(blobFeeCap),
   337→		BlobHashes: versionedHashes,
   338→		Sidecar: &types.BlobTxSidecar{
   339→			Blobs:       blobs,
   340→			Commitments: comms,
   341→			Proofs:      proofs,
   342→		},
   343→	})
   344→	return tx
   345→}
   346→
   347→func encodeBlobs(data []byte) []kzg4844.Blob {
   348→	blobs := []kzg4844.Blob{{}}
   349→	blobIndex := 0
   350→	fieldIndex := -1
   351→	numOfElems := fieldparams.BlobLength / 32
   352→	for i := 0; i < len(data); i += 31 {
   353→		fieldIndex++
   354→		if fieldIndex == numOfElems {
   355→			if blobIndex >= 1 {
   356→				break
   357→			}
   358→			blobs = append(blobs, kzg4844.Blob{})
   359→			blobIndex++
   360→			fieldIndex = 0
   361→		}
   362→		max := i + 31
   363→		if max > len(data) {
   364→			max = len(data)
   365→		}
   366→		copy(blobs[blobIndex][fieldIndex*32+1:], data[i:max])
   367→	}
   368→	return blobs
   369→}
   370→
   371→func EncodeBlobs(data []byte) ([]kzg4844.Blob, []kzg4844.Commitment, []kzg4844.Proof, []common.Hash, error) {
   372→	var (
   373→		blobs           = encodeBlobs(data)
   374→		commits         []kzg4844.Commitment
   375→		proofs          []kzg4844.Proof
   376→		versionedHashes []common.Hash
   377→	)
   378→	for _, blob := range blobs {
   379→		b := blob
   380→		commit, err := kzg4844.BlobToCommitment(&b)
   381→		if err != nil {
   382→			return nil, nil, nil, nil, err
   383→		}
   384→		commits = append(commits, commit)
   385→
   386→		proof, err := kzg4844.ComputeBlobProof(&b, commit)
   387→		if err != nil {
   388→			return nil, nil, nil, nil, err
   389→		}
   390→		if err := kzg4844.VerifyBlobProof(&b, commit, proof); err != nil {
   391→			return nil, nil, nil, nil, err
   392→		}
   393→		proofs = append(proofs, proof)
   394→
   395→		versionedHashes = append(versionedHashes, kZGToVersionedHash(commit))
   396→	}
   397→	return blobs, commits, proofs, versionedHashes, nil
   398→}
   399→
   400→var blobCommitmentVersionKZG uint8 = 0x01
   401→
   402→// kZGToVersionedHash implements kzg_to_versioned_hash from EIP-4844
   403→func kZGToVersionedHash(kzg kzg4844.Commitment) common.Hash {
   404→	h := sha256.Sum256(kzg[:])
   405→	h[0] = blobCommitmentVersionKZG
   406→
   407→	return h
   408→}
