   441→func getCaps(rpc *rpc.Client, defaultGasPrice *big.Int) (*big.Int, *big.Int, error) {
   442→	if rpc == nil {
   443→		tip := new(big.Int).Mul(big.NewInt(1), big.NewInt(0).SetUint64(params.BeaconConfig().GweiPerEth))
   444→		if defaultGasPrice.Cmp(tip) >= 0 {
   445→			feeCap := new(big.Int).Sub(defaultGasPrice, tip)
   446→			return tip, feeCap, nil
   447→		}
   448→		return big.NewInt(0), defaultGasPrice, nil
   449→	}
   450→	client := ethclient.NewClient(rpc)
   451→	tip, err := client.SuggestGasTipCap(context.Background())
   452→	if err != nil {
   453→		return nil, nil, err
   454→	}
   455→	feeCap, err := client.SuggestGasPrice(context.Background())
   456→	return tip, feeCap, err
   457→}
