    22→// ErrNoBuilder is used when builder endpoint is not configured.
    23→var ErrNoBuilder = errors.New("builder endpoint not configured")
    24→
    25→// BlockBuilder defines the interface for interacting with the block builder
    26→type BlockBuilder interface {
    27→	SubmitBlindedBlock(ctx context.Context, block interfaces.ReadOnlySignedBeaconBlock) (interfaces.ExecutionData, v1.BlobsBundler, error)
    28→	SubmitBlindedBlockPostFulu(ctx context.Context, block interfaces.ReadOnlySignedBeaconBlock) error
    29→	GetHeader(ctx context.Context, slot primitives.Slot, parentHash [32]byte, pubKey [48]byte) (builder.SignedBid, error)
    30→	RegisterValidator(ctx context.Context, reg []*ethpb.SignedValidatorRegistrationV1) error
    31→	RegistrationByValidatorID(ctx context.Context, id primitives.ValidatorIndex) (*ethpb.ValidatorRegistrationV1, error)
    32→	Configured() bool
    33→}
    34→
    35→// config defines a config struct for dependencies into the service.
    36→type config struct {
    37→	builderClient builder.BuilderClient
    38→	beaconDB      db.HeadAccessDatabase
    39→	headFetcher   blockchain.HeadFetcher
    40→}
    41→
    42→// Service defines a service that provides a client for interacting with the beacon chain and MEV relay network.
    43→type Service struct {
    44→	cfg               *config
    45→	c                 builder.BuilderClient
    46→	ctx               context.Context
    47→	cancel            context.CancelFunc
    48→	registrationCache *cache.RegistrationCache
    49→}
    50→
    51→// NewService instantiates a new service.
    52→func NewService(ctx context.Context, opts ...Option) (*Service, error) {
    53→	ctx, cancel := context.WithCancel(ctx)
    54→	s := &Service{
    55→		ctx:    ctx,
    56→		cancel: cancel,
    57→		cfg:    &config{},
    58→	}
    59→	for _, opt := range opts {
    60→		if err := opt(s); err != nil {
    61→			return nil, err
    62→		}
    63→	}
    64→	if s.cfg.builderClient != nil && !reflect.ValueOf(s.cfg.builderClient).IsNil() {
    65→		s.c = s.cfg.builderClient
    66→
    67→		// Is the builder up?
    68→		if err := s.c.Status(ctx); err != nil {
    69→			log.WithError(err).Error("Failed to check builder status")
    70→		} else {
    71→			log.WithField("endpoint", s.c.NodeURL()).Info("Builder has been configured")
    72→			log.Warn("Outsourcing block construction to external builders adds non-trivial delay to block propagation time. " +
    73→				"Builder-constructed blocks or fallback blocks may get orphaned. Use at your own risk!")
    74→		}
    75→	}
    76→	return s, nil
    77→}
