    90→// SubmitBlindedBlock submits a blinded block to the builder relay network.
    91→func (s *Service) SubmitBlindedBlock(ctx context.Context, b interfaces.ReadOnlySignedBeaconBlock) (interfaces.ExecutionData, v1.BlobsBundler, error) {
    92→	ctx, span := trace.StartSpan(ctx, "builder.SubmitBlindedBlock")
    93→	defer span.End()
    94→	start := time.Now()
    95→	defer func() {
    96→		submitBlindedBlockLatency.Observe(float64(time.Since(start).Milliseconds()))
    97→	}()
    98→	if s.c == nil {
    99→		return nil, nil, ErrNoBuilder
   100→	}
   101→
   102→	return s.c.SubmitBlindedBlock(ctx, b)
   103→}
