   121→// GetHeader retrieves the header for a given slot and parent hash from the builder relay network.
   122→func (s *Service) GetHeader(ctx context.Context, slot primitives.Slot, parentHash [32]byte, pubKey [48]byte) (builder.SignedBid, error) {
   123→	ctx, span := trace.StartSpan(ctx, "builder.GetHeader")
   124→	defer span.End()
   125→	start := time.Now()
   126→	defer func() {
   127→		getHeaderLatency.Observe(float64(time.Since(start).Milliseconds()))
   128→	}()
   129→	if s.c == nil {
   130→		tracing.AnnotateError(span, ErrNoBuilder)
