   149→// RegisterValidator registers a validator with the builder relay network.
   150→// It also saves the registration object to the DB.
   151→func (s *Service) RegisterValidator(ctx context.Context, reg []*ethpb.SignedValidatorRegistrationV1) error {
   152→	ctx, span := trace.StartSpan(ctx, "builder.RegisterValidator")
   153→	defer span.End()
   154→	start := time.Now()
   155→	defer func() {
   156→		registerValidatorLatency.Observe(float64(time.Since(start).Milliseconds()))
   157→	}()
   158→	if s.c == nil {
   159→		return ErrNoBuilder
   160→	}
   161→
   162→	// should be removed if db is removed
   163→	idxs := make([]primitives.ValidatorIndex, 0)
   164→	msgs := make([]*ethpb.ValidatorRegistrationV1, 0)
   165→
   166→	indexToRegistration := make(map[primitives.ValidatorIndex]*ethpb.ValidatorRegistrationV1)
   167→
   168→	valid := make([]*ethpb.SignedValidatorRegistrationV1, 0)
   169→	for i := 0; i < len(reg); i++ {
   170→		r := reg[i]
   171→		nx, exists := s.cfg.headFetcher.HeadPublicKeyToValidatorIndex(bytesutil.ToBytes48(r.Message.Pubkey))
   172→		if !exists {
   173→			// we want to allow validators to set up keys that haven't been added to the beaconstate validator list yet,
   174→			// so we should tolerate keys that do not seem to be valid by skipping past them.
   175→			log.Warnf("Skipping validator registration for pubkey=%#x - not in current validator set.", r.Message.Pubkey)
   176→			continue
   177→		}
   178→		idxs = append(idxs, nx)
   179→		msgs = append(msgs, r.Message)
   180→		valid = append(valid, r)
   181→		indexToRegistration[nx] = r.Message
   182→	}
   183→	if err := s.c.RegisterValidator(ctx, valid); err != nil {
   184→		return errors.Wrap(err, "could not register validator(s)")
   185→	}
   186→
   187→	if len(indexToRegistration) != len(msgs) {
   188→		return errors.New("ids and registrations must be the same length")
   189→	}
   190→	if s.registrationCache != nil {
   191→		s.registrationCache.UpdateIndexToRegisteredMap(ctx, indexToRegistration)
   192→		return nil
   193→	} else {
   194→		return s.cfg.beaconDB.SaveRegistrationsByValidatorIDs(ctx, idxs, msgs)
   195→	}
   196→}
   197→
   198→// RegistrationByValidatorID returns either the values from the cache or db.
   199→func (s *Service) RegistrationByValidatorID(ctx context.Context, id primitives.ValidatorIndex) (*ethpb.ValidatorRegistrationV1, error) {
   200→	if s.registrationCache != nil {
   201→		return s.registrationCache.RegistrationByIndex(id)
   202→	} else {
   203→		if s.cfg == nil || s.cfg.beaconDB == nil {
   204→			return nil, errors.New("nil beacon db")
   205→		}
   206→		return s.cfg.beaconDB.RegistrationByValidatorID(ctx, id)
   207→	}
   208→}
