   210→// Configured returns true if the user has configured a builder client.
   211→func (s *Service) Configured() bool {
   212→	return s.c != nil && !reflect.ValueOf(s.c).IsNil()
   213→}
   214→
   215→func (s *Service) pollRelayerStatus(ctx context.Context) {
   216→	ticker := time.NewTicker(time.Minute)
   217→	defer ticker.Stop()
   218→	for {
   219→		select {
   220→		case <-ticker.C:
   221→			if s.c != nil {
   222→				if err := s.c.Status(ctx); err != nil {
   223→					log.WithError(err).Error("Failed to call relayer status endpoint, perhaps mev-boost or relayers are down")
   224→				}
   225→			}
   226→		case <-ctx.Done():
   227→			return
   228→		}
   229→	}
   230→}
