    16→// Returns true if builder (ie outsourcing block construction) can be used. Both conditions have to meet:
    17→// - Validator has registered to use builder (ie called registerBuilder API end point)
    18→// - Circuit breaker has not been activated (ie the liveness of the chain is healthy)
    19→func (vs *Server) canUseBuilder(ctx context.Context, slot primitives.Slot, idx primitives.ValidatorIndex) (bool, error) {
    20→	ctx, span := trace.StartSpan(ctx, "ProposerServer.canUseBuilder")
    21→	defer span.End()
    22→
    23→	if !vs.BlockBuilder.Configured() {
    24→		return false, nil
    25→	}
    26→	activated, err := vs.circuitBreakBuilder(slot)
    27→	span.SetAttributes(trace.BoolAttribute("circuitBreakerActivated", activated))
    28→	if err != nil {
    29→		tracing.AnnotateError(span, err)
    30→		return false, err
    31→	}
    32→	if activated {
    33→		return false, nil
    34→	}
    35→	return vs.validatorRegistered(ctx, idx)
    36→}
    37→
    38→// validatorRegistered returns true if validator with index `id` was previously registered in the database.
    39→func (vs *Server) validatorRegistered(ctx context.Context, id primitives.ValidatorIndex) (bool, error) {
    40→	if vs.BlockBuilder == nil {
    41→		return false, nil
    42→	}
    43→	_, err := vs.BlockBuilder.RegistrationByValidatorID(ctx, id)
    44→	switch {
    45→	case errors.Is(err, kv.ErrNotFoundFeeRecipient), errors.Is(err, cache.ErrNotFoundRegistration):
    46→		return false, nil
    47→	case err != nil:
    48→		return false, err
    49→	}
    50→	return true, nil
    51→}
    52→
    53→// circuitBreakBuilder returns true if the builder is not allowed to be used due to circuit breaker conditions.
    54→func (vs *Server) circuitBreakBuilder(s primitives.Slot) (bool, error) {
    55→	if vs.ForkchoiceFetcher == nil {
    56→		return true, errors.New("no fork choicer configured")
    57→	}
    58→
    59→	// Circuit breaker is active if the missing consecutive slots greater than `MaxBuilderConsecutiveMissedSlots`.
    60→	highestReceivedSlot := vs.ForkchoiceFetcher.HighestReceivedBlockSlot()
    61→	maxConsecutiveSkipSlotsAllowed := params.BeaconConfig().MaxBuilderConsecutiveMissedSlots
    62→	diff, err := s.SafeSubSlot(highestReceivedSlot)
    63→	if err != nil {
    64→		return true, err
    65→	}
    66→
    67→	if diff >= maxConsecutiveSkipSlotsAllowed {
    68→		log.WithFields(logrus.Fields{
    69→			"currentSlot":                    s,
    70→			"highestReceivedSlot":            highestReceivedSlot,
    71→			"maxConsecutiveSkipSlotsAllowed": maxConsecutiveSkipSlotsAllowed,
    72→		}).Warn("Circuit breaker activated due to missing consecutive slot. Ignore if mev-boost is not used")
    73→		return true, nil
    74→	}
    75→
    76→	// Not much reason to check missed slots epoch rolling window if input slot is less than epoch.
    77→	if s < params.BeaconConfig().SlotsPerEpoch {
    78→		return false, nil
    79→	}
    80→
    81→	// Circuit breaker is active if the missing slots per epoch (rolling window) greater than `MaxBuilderEpochMissedSlots`.
    82→	receivedCount, err := vs.ForkchoiceFetcher.ReceivedBlocksLastEpoch()
    83→	if err != nil {
    84→		return true, err
    85→	}
    86→	maxEpochSkipSlotsAllowed := params.BeaconConfig().MaxBuilderEpochMissedSlots
    87→	diff, err = params.BeaconConfig().SlotsPerEpoch.SafeSub(receivedCount)
    88→	if err != nil {
    89→		return true, err
    90→	}
    91→	if diff >= maxEpochSkipSlotsAllowed {
    92→		log.WithFields(logrus.Fields{
    93→			"totalMissed":              diff,
    94→			"maxEpochSkipSlotsAllowed": maxEpochSkipSlotsAllowed,
    95→		}).Warn("Circuit breaker activated due to missing enough slots last epoch. Ignore if mev-boost is not used")
    96→		return true, nil
    97→	}
    98→
    99→	return false, nil
   100→}

