    28→// WithdrawalRequest is the message from the execution layer to trigger the
    29→// withdrawal of a validator's balance to its withdrawal address new in Electra
    30→message WithdrawalRequest {
    31→  // The execution address receiving the funds
    32→  bytes source_address = 1 [ (ethereum.eth.ext.ssz_size) = "20" ];
    33→
    34→  // 48 byte BLS public key of the validator.
    35→  bytes validator_pubkey = 2 [ (ethereum.eth.ext.ssz_size) = "48" ];
    36→
    37→  // Deposit amount in gwei.
    38→  uint64 amount = 3;
    39→}
    40→
    41→// DepositRequest is the message from the execution layer to trigger the deposit
    42→// of a validator's balance to its balance new in Electra
    43→message DepositRequest {
    44→  bytes pubkey = 1 [ (ethereum.eth.ext.ssz_size) = "48" ];
    45→  bytes withdrawal_credentials = 2 [ (ethereum.eth.ext.ssz_size) = "32" ];
    46→  uint64 amount = 3;
    47→  bytes signature = 4 [ (ethereum.eth.ext.ssz_size) = "96" ];
    48→  uint64 index = 5;
    49→}
    50→
    51→// ConsolidationRequest is the message from the execution layer to trigger the
    52→// consolidation of one validator to another validator.
    53→message ConsolidationRequest {
    54→  // Source address of account which originated the request.
    55→  bytes source_address = 1 [ (ethereum.eth.ext.ssz_size) = "20" ];
    56→  // Funds will be moved from this public key.
    57→  bytes source_pubkey = 2 [ (ethereum.eth.ext.ssz_size) = "48" ];
    58→  // Funds will be moved to this public key.
    59→  bytes target_pubkey = 3 [ (ethereum.eth.ext.ssz_size) = "48" ];
    60→}
    61→
    62→// ExecutionRequests is a container that contains all the requests from the
    63→// execution layer to be included in a block
    64→message ExecutionRequests {
    65→  repeated DepositRequest deposits = 1
    66→      [ (ethereum.eth.ext.ssz_max) = "max_deposit_requests_per_payload.size" ];
    67→  repeated WithdrawalRequest withdrawals = 2
    68→      [ (ethereum.eth.ext.ssz_max) =
    69→            "max_withdrawal_requests_per_payload.size" ];
    70→  repeated ConsolidationRequest consolidations = 3
    71→      [ (ethereum.eth.ext.ssz_max) =
    72→            "max_consolidation_requests_per_payload.size" ];
    73→}
    74→
    75→// ExecutionBundleElectra is a container that builds on Payload V4 and includes
    76→// execution requests sidecar needed post Electra
    77→message ExecutionBundleElectra {
    78→  ExecutionPayloadDeneb payload = 1;
    79→  bytes value = 2;
    80→  BlobsBundle blobs_bundle = 3;
    81→  bool should_override_builder = 4;
    82→  repeated bytes execution_requests = 5;
    83→}
