    24→// NewWrappedExecutionData creates an appropriate execution payload wrapper based on the incoming type.
    25→func NewWrappedExecutionData(v proto.Message) (interfaces.ExecutionData, error) {
    26→	if v == nil {
    27→		return nil, consensus_types.ErrNilObjectWrapped
    28→	}
    29→	switch pbStruct := v.(type) {
    30→	case *enginev1.ExecutionPayload:
    31→		return WrappedExecutionPayload(pbStruct)
    32→	case *enginev1.ExecutionPayloadCapella:
    33→		return WrappedExecutionPayloadCapella(pbStruct)
    34→	case *enginev1.ExecutionPayloadCapellaWithValue:
    35→		return WrappedExecutionPayloadCapella(pbStruct.Payload)
    36→	case *enginev1.ExecutionPayloadDeneb:
    37→		return WrappedExecutionPayloadDeneb(pbStruct)
    38→	case *enginev1.ExecutionPayloadDenebWithValueAndBlobsBundle:
    39→		return WrappedExecutionPayloadDeneb(pbStruct.Payload)
    40→	case *enginev1.ExecutionBundleElectra:
    41→		// note: no payload changes in electra so using deneb
    42→		return WrappedExecutionPayloadDeneb(pbStruct.Payload)
    43→	case *enginev1.ExecutionBundleFulu:
    44→		return WrappedExecutionPayloadDeneb(pbStruct.Payload)
    45→	default:
    46→		return nil, errors.Wrapf(ErrUnsupportedVersion, "type %T", pbStruct)
    47→	}
    48→}
